import{describe,it,expect,beforeEach}from"vitest";import fs from"fs";import path from"path";describe("How India Changes Across States Explorer",()=>{let t,e;beforeEach(()=>{t=fs.readFileSync(path.resolve(__dirname,"../../frontend/state-border-changes/state-border-changes.js"),"utf-8"),e=fs.readFileSync(path.resolve(__dirname,"../../frontend/state-border-changes/state-border-changes.html"),"utf-8")}),it("contains state border data for cultural and geographical dimensions",()=>{expect(t).toContain("STATE_DATA"),expect(t).toContain("DIMENSIONS"),expect(t).toContain("Punjab"),expect(t).toContain("Rajasthan"),expect(t).toContain("Tamil Nadu"),expect(t).toContain("Kerala")}),it("covers language, food, attire, climate, architecture, and traditions",()=>{expect(t).toContain("Language & Script"),expect(t).toContain("Cuisine & Food"),expect(t).toContain("Attire & Dress"),expect(t).toContain("Climate & Geography"),expect(t).toContain("Architecture & Dwellings"),expect(t).toContain("Traditions & Festivals")}),it("includes interactive selectors and preset border chips",()=>{expect(e).toContain('id="from-state-select"'),expect(e).toContain('id="to-state-select"'),expect(e).toContain('id="swap-states-btn"'),expect(e).toContain('id="bc-search-input"'),expect(e).toContain('class="bc-preset-chip"')})});